// listEnvelopeMetadataKeys are top-level keys that, when accompanying a
// list-wrapper array, suggest the response is a paginated list envelope
// rather than a detail object. Used by writeThroughCache to decide
// whether to upsert a single-object body. Any envelope key NOT in this
// set (and not a list wrapper itself) signals real per-row data, and
// the envelope is treated as a detail object even when one of its
// wrapper-named fields happens to be an empty array.
var listEnvelopeMetadataKeys = map[string]bool{
	// list wrappers themselves — must stay in sync with pageItemKeys
	"results": true, "data": true, "items": true,
	"records": true, "nodes": true, "entries": true, "features": true,
	"Results": true, "Data": true, "Items": true,
	"Records": true, "Nodes": true, "Entries": true, "Features": true,
	// pagination cursors / tokens
	"next_cursor": true, "nextCursor": true,
	"next_page_token": true, "nextPageToken": true,
	"page_token": true, "pageToken": true,
	"end_cursor": true, "endCursor": true,
	"start_cursor": true, "startCursor": true,
	"cursor": true, "after": true, "before": true,
	// has-more flags and page numbers
	"has_more": true, "hasMore": true, "has_next": true, "hasNext": true,
	"next_page": true, "previous_page": true,
	"page": true, "page_size": true, "per_page": true,
	// counts / totals
	"total": true, "count": true, "size": true, "total_count": true, "totalCount": true,
	// JSend / common status envelopes
	"success": true, "status": true, "message": true, "error": true,
	"errors": true, "Errors": true, "warnings": true, "Warnings": true,
	// wrapper objects
	"links": true, "meta": true, "pagination": true,
	"response_metadata": true, "paging": true,
	// links shape
	"next": true, "prev": true, "previous": true, "first": true, "last": true,
}

var writeThroughListWrapperKeys = []string{
	"data", "results", "items", "records", "nodes", "entries", "features",
	"Data", "Results", "Items", "Records", "Nodes", "Entries", "Features",
}
var writeThroughNestedEnvelopeKeys = []string{"data", "Data", "result", "Result"}

// writeThroughCache upserts live API results into the local SQLite store so
// FTS search covers everything the user has looked up — not just explicit syncs.
// Best-effort: failures are silently ignored (the live result already succeeded).
func writeThroughCache(ctx context.Context, resourceType string, data json.RawMessage) {
	db, err := store.OpenWithContext(ctx, defaultDBPath("scryfall-pp-cli"))
	if err != nil {
		return
	}
	defer db.Close()

	// Collect items to upsert from various response shapes
	var items []json.RawMessage

	// Try direct array first
	if json.Unmarshal(data, &items) != nil || len(items) == 0 {
		items = nil
		// Try object — check for common envelope patterns (results, data, items)
		var envelope map[string]json.RawMessage
		if json.Unmarshal(data, &envelope) == nil {
			matchedListEnvelope := false
			if extracted, ok := extractWriteThroughListItems(envelope); ok {
				matchedListEnvelope = true
				items = extracted
			}
			if matchedListEnvelope && len(items) == 0 {
				return
			}
			// Single object detail response: let UpsertBatch's existing
			// resourceIDFieldOverrides mechanism resolve the primary key.
			// Guarding on envelope["id"] dropped any API whose PK is named
			// CertNo / sku / invoiceId / etc. on the floor (#1439).
			//
			// Treat the envelope as a list-shaped response only when EVERY
			// top-level key is either a list-wrapper (results/data/items)
			// holding a real array, or a known pagination-metadata key.
			// A detail object that happens to carry an empty wrapper-named
			// field alongside real data (e.g. {"id":"order","items":[],
			// "status":"pending"}) must still cache as a single row.
			if items == nil && !matchedListEnvelope && len(envelope) > 0 {
				looksLikeListEnvelope := false
				hasListWrapperArray := false
				for _, key := range writeThroughListWrapperKeys {
					raw, ok := envelope[key]
					if !ok {
						continue
					}
					// json.Unmarshal("null", &arr) succeeds with arr=nil,
					// so require arr != nil to keep true empty arrays in
					// the skip branch while letting scalar/null values fall
					// through as regular field-name collisions.
					var arr []json.RawMessage
					if json.Unmarshal(raw, &arr) == nil && arr != nil {
						hasListWrapperArray = true
						break
					}
				}
				if hasListWrapperArray {
					looksLikeListEnvelope = true
					for k := range envelope {
						if !listEnvelopeMetadataKeys[k] {
							looksLikeListEnvelope = false
							break
						}
					}
				}
				if !looksLikeListEnvelope {
					_, _, _ = db.UpsertBatch(resourceType, []json.RawMessage{data})
					return
				}
			}
		}
	}

	if len(items) > 0 {
		_, _, _ = db.UpsertBatch(resourceType, items)
	}
}

type writeThroughArrayDecoder func(json.RawMessage) ([]json.RawMessage, bool)

func extractWriteThroughListItems(envelope map[string]json.RawMessage) ([]json.RawMessage, bool) {
	if items, ok := extractWriteThroughListWrapperItems(envelope, decodeWriteThroughNonEmptyArray); ok {
		return items, true
	}

	for _, key := range writeThroughNestedEnvelopeKeys {
		raw, ok := envelope[key]
		if !ok || isRawJSONNull(raw) {
			continue
		}
		var inner map[string]json.RawMessage
		if json.Unmarshal(raw, &inner) != nil {
			continue
		}
		if items, ok := extractNestedWriteThroughListItems(inner); ok {
			return items, true
		}
	}

	return extractWriteThroughSingleArraySibling(envelope, decodeWriteThroughNonEmptyArray)
}

func extractNestedWriteThroughListItems(envelope map[string]json.RawMessage) ([]json.RawMessage, bool) {
	if items, ok := extractWriteThroughListWrapperItems(envelope, decodeWriteThroughArray); ok {
		return items, true
	}
	return extractWriteThroughSingleArraySibling(envelope, decodeWriteThroughArray)
}

func extractWriteThroughListWrapperItems(envelope map[string]json.RawMessage, decode writeThroughArrayDecoder) ([]json.RawMessage, bool) {
	for _, key := range writeThroughListWrapperKeys {
		raw, ok := envelope[key]
		if !ok {
			continue
		}
		if items, ok := decode(raw); ok {
			return items, true
		}
	}
	return nil, false
}

func extractWriteThroughSingleArraySibling(envelope map[string]json.RawMessage, decode writeThroughArrayDecoder) ([]json.RawMessage, bool) {
	arrayCount := 0
	var arrayItems []json.RawMessage
	for key, raw := range envelope {
		if listEnvelopeMetadataKeys[key] {
			continue
		}
		if candidate, ok := decode(raw); ok {
			if !writeThroughArrayItemsAreObjects(candidate) {
				continue
			}
			arrayItems = candidate
			arrayCount++
			continue
		}
		return nil, false
	}
	if arrayCount == 1 {
		return arrayItems, true
	}
	return nil, false
}

func writeThroughArrayItemsAreObjects(items []json.RawMessage) bool {
	if len(items) == 0 {
		return true
	}
	var obj map[string]json.RawMessage
	return json.Unmarshal(items[0], &obj) == nil
}

func decodeWriteThroughNonEmptyArray(raw json.RawMessage) ([]json.RawMessage, bool) {
	items, ok := decodeWriteThroughArray(raw)
	if !ok || len(items) == 0 {
		return nil, false
	}
	return items, true
}

func decodeWriteThroughArray(raw json.RawMessage) ([]json.RawMessage, bool) {
	var items []json.RawMessage
	if json.Unmarshal(raw, &items) != nil || items == nil {
		return nil, false
	}
	return items, true
}

func isRawJSONNull(raw json.RawMessage) bool {
	return strings.TrimSpace(string(raw)) == "null"
}

func writeMutationResponseToStore(ctx context.Context, resourceType string, data json.RawMessage, responsePath string) {
	items := mutationResponseEntityItems(resourceType, data, responsePath)
	if len(items) == 0 {
		return
	}

	db, err := store.OpenWithContext(ctx, defaultDBPath("scryfall-pp-cli"))
	if err != nil {
		return
	}
	defer db.Close()

	_, _, _ = db.UpsertBatch(resourceType, items)
}

func mutationResponseEntityItems(resourceType string, data json.RawMessage, responsePath string) []json.RawMessage {
	if responsePath != "" {
		if pathData, ok := responsePayloadAtPath(data, responsePath); ok {
			data = pathData
		}
	}

	if items := mutationResponseItemsFromPayload(resourceType, data); len(items) > 0 {
		return items
	}

	data = mutationResponsePayload(data)
	if items := mutationResponseItemsFromPayload(resourceType, data); len(items) > 0 {
		return items
	}

	if responsePath == "" {
		var envelope map[string]json.RawMessage
		if json.Unmarshal(data, &envelope) == nil {
			if _, hasStatus := envelope["status"]; !hasStatus {
				if raw, ok := envelope["data"]; ok {
					return mutationResponseItemsFromPayload(resourceType, raw)
				}
			}
		}
	}

	return nil
}

func mutationResponseItemsFromPayload(resourceType string, data json.RawMessage) []json.RawMessage {
	if len(bytes.TrimSpace(data)) == 0 {
		return nil
	}

	var arr []json.RawMessage
	if json.Unmarshal(data, &arr) == nil {
		items := make([]json.RawMessage, 0, len(arr))
		for _, item := range arr {
			if mutationResponseHasID(resourceType, item) {
				items = append(items, item)
			}
		}
		return items
	}

	if mutationResponseHasID(resourceType, data) {
		return []json.RawMessage{data}
	}
	return nil
}

func mutationResponsePayload(data json.RawMessage) json.RawMessage {
	var envelope struct {
		Status string          `json:"status"`
		Data   json.RawMessage `json:"data"`
	}
	if err := json.Unmarshal(data, &envelope); err != nil || envelope.Status == "" || envelope.Data == nil {
		return data
	}
	switch envelope.Status {
	case "success", "ok", "OK", "Success":
		return envelope.Data
	default:
		return data
	}
}

func mutationResponseHasID(resourceType string, data json.RawMessage) bool {
	var obj map[string]any
	if err := json.Unmarshal(data, &obj); err != nil || len(obj) == 0 {
		return false
	}
	if synthetic, _ := obj["__pp_verify_synthetic__"].(bool); synthetic {
		return false
	}
	return store.ExtractResourceID(resourceType, obj) != ""
}

// resolveLocal reads data from the local SQLite store. Collection reads normally
// return every synced record for the resource type. Scryfall search/autocomplete
// semantics are deliberately rejected because returning the full card cache for
// a filtered request is unsafe: a caller must never mistake unrelated cards for
// successful search results during an outage.
func resolveLocal(ctx context.Context, flags *rootFlags, hintWriter io.Writer, resourceType string, isList bool, path string, params map[string]string, reason string) (json.RawMessage, DataProvenance, error) {
	db, err := openStoreForRead(ctx, "scryfall-pp-cli")
	if err != nil {
		return nil, DataProvenance{}, fmt.Errorf("opening local database: %w\nRun 'scryfall-pp-cli sync' first.", err)
	}
	if db == nil {
		return nil, DataProvenance{}, fmt.Errorf("no local data. Run 'scryfall-pp-cli sync' first")
	}
	defer db.Close()

	if flags != nil {
		emitSyncHints(hintWriter, db, resourceType, flags.maxAge)
	}

	prov := localProvenance(db, resourceType, reason)

	if err := validateScryfallLocalRead(path, params); err != nil {
		return nil, DataProvenance{}, err
	}

	// Warn if endpoint had filters that local reads can't reproduce
	if len(params) > 0 {
		fmt.Fprintf(os.Stderr, "warning: local data is unfiltered — endpoint filters are not applied to cached data\n")
	}

	if isList {
		raw, err := db.List(resourceType, 0) // 0 = no limit, return all synced data
		if err != nil {
			return nil, DataProvenance{}, fmt.Errorf("querying local store: %w", err)
		}
		// Filter out empty/invalid records (empty arrays, null, whitespace-only)
		// that can end up in the store from pagination boundary artifacts.
		var items []json.RawMessage
		for _, r := range raw {
			trimmed := strings.TrimSpace(string(r))
			if trimmed == "" || trimmed == "null" || trimmed == "[]" || trimmed == "{}" {
				continue
			}
			items = append(items, r)
		}
		if len(items) == 0 {
			return nil, DataProvenance{}, fmt.Errorf("no local data for %q. Run 'scryfall-pp-cli sync' first", resourceType)
		}
		// Marshal []json.RawMessage into a single JSON array
		data, err := json.Marshal(items)
		if err != nil {
			return nil, DataProvenance{}, fmt.Errorf("marshaling local data: %w", err)
		}
		return data, prov, nil
	}

	// Try the primary stored ID first, then endpoint-specific alternate keys.
	// Scryfall stores cards and sets by UUID, while several supported routes use
	// numeric marketplace IDs, set codes, or names instead.
	parts := strings.Split(strings.TrimRight(path, "/"), "/")
	id := parts[len(parts)-1]

	item, err := db.Get(resourceType, id)
	if err != nil {
		if !errors.Is(err, sql.ErrNoRows) {
			return nil, DataProvenance{}, fmt.Errorf("querying local store: %w", err)
		}
		item, err = resolveScryfallAlternateLocalDetail(ctx, db, resourceType, path, params)
		if err != nil {
			return nil, DataProvenance{}, err
		}
	}
	return item, prov, nil
}

// validateScryfallLocalRead rejects filtered operations whose live semantics
// cannot be reproduced from the generic local mirror. In particular, Scryfall's
// card-search query language supports operators, comparisons, and ordering that
// a plain cache scan cannot implement faithfully. Explicit failure is safer than
// returning every cached card as if it matched.
func validateScryfallLocalRead(path string, params map[string]string) error {
	// The local mirror stores JSON resources. It cannot reproduce alternate
	// image or text representations, nor face/version rendering options.
	if path == "/cards" || strings.HasPrefix(path, "/cards/") || strings.HasPrefix(path, "/sets") {
		if format := strings.TrimSpace(params["format"]); format != "" && !strings.EqualFold(format, "json") {
			return fmt.Errorf("local data cannot reproduce Scryfall %q format; use --data-source live", format)
		}
		if strings.TrimSpace(params["face"]) != "" || strings.TrimSpace(params["version"]) != "" {
			return fmt.Errorf("local data cannot reproduce Scryfall face or version options; use --data-source live")
		}
	}
	switch strings.TrimRight(path, "/") {
	case "/cards/search":
		query := strings.TrimSpace(params["q"])
		if query == "" {
			query = "<empty>"
		}
		return fmt.Errorf("local data cannot safely reproduce Scryfall card search query %q; retry with --data-source live when the API is reachable", query)
	case "/cards/autocomplete":
		return fmt.Errorf("local data cannot safely reproduce Scryfall card autocomplete; retry with --data-source live when the API is reachable")
	case "/cards/random":
		return fmt.Errorf("local data cannot safely reproduce Scryfall random-card selection; retry with --data-source live when the API is reachable")
	default:
		return nil
	}
}

// resolveScryfallAlternateLocalDetail resolves the alternate identifiers used
// by Scryfall detail routes after the primary UUID lookup has missed.
func resolveScryfallAlternateLocalDetail(ctx context.Context, db *store.Store, resourceType, path string, params map[string]string) (json.RawMessage, error) {
	matcher, description, err := scryfallLocalDetailMatcher(resourceType, path, params)
	if err != nil {
		return nil, err
	}
	if matcher == nil {
		parts := strings.Split(strings.TrimRight(path, "/"), "/")
		id := parts[len(parts)-1]
		return nil, fmt.Errorf("resource %q with ID %q not found in local store. Run 'scryfall-pp-cli sync' first", resourceType, id)
	}

	query := `SELECT data FROM resources WHERE resource_type = ?`
	args := []any{resourceType}
	// Older read-only mirrors may not have the v10 index until the next sync.
	// Keep their existing lookup behavior; current mirrors use the indexed key.
	version, err := db.SchemaVersion()
	if err != nil {
		return nil, fmt.Errorf("reading local store schema: %w", err)
	}
	if version >= 10 {
		kind, value := scryfallLocalAlias(resourceType, path, params)
		// SQLite's lower() used by the one-time v9 backfill only folds
		// ASCII. Keep Unicode names on the exact JSON matcher so a case
		// difference cannot hide a valid card in an upgraded mirror.
		if kind != "" && asciiAliasValue(value) {
			query = `SELECT r.data FROM resource_alt_keys a JOIN resources r ON r.resource_type = a.resource_type AND r.id = a.resource_id WHERE a.resource_type = ? AND a.kind = ? AND a.value = ?`
			args = append(args, kind, strings.ToLower(value))
		}
	}
	rows, err := db.DB().QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("querying local store for %s: %w", description, err)
	}
	defer rows.Close()
	var match json.RawMessage
	matchCount := 0
	for rows.Next() {
		var data string
		if err := rows.Scan(&data); err != nil {
			return nil, fmt.Errorf("reading local store for %s: %w", description, err)
		}
		item := json.RawMessage(data)
		object, decodeErr := store.DecodeJSONObject(item)
		if decodeErr != nil || !matcher(object) {
			continue
		}
		match = item
		matchCount++
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("reading local store for %s: %w", description, err)
	}
	if matchCount == 0 {
		return nil, fmt.Errorf("%s not found in local store. Run 'scryfall-pp-cli sync' first", description)
	}
	if matchCount > 1 {
		return nil, fmt.Errorf("%s is ambiguous in local data (%d matches); use a primary Scryfall UUID or --data-source live", description, matchCount)
	}
	return match, nil
}

func asciiAliasValue(value string) bool {
	for _, r := range value {
		if r > 127 {
			return false
		}
	}
	return true
}

func scryfallLocalAlias(resourceType, path string, params map[string]string) (string, string) {
	segments := strings.Split(strings.Trim(path, "/"), "/")
	if resourceType == "cards" && len(segments) >= 2 && segments[0] == "cards" {
		switch segments[1] {
		case "named":
			return "name", strings.TrimSpace(params["exact"])
		case "arena":
			return "arena_id", lastPathSegment(segments)
		case "mtgo":
			return "mtgo_id", lastPathSegment(segments)
		case "multiverse":
			return "multiverse_ids", lastPathSegment(segments)
		case "tcgplayer":
			return "tcgplayer_id", lastPathSegment(segments)
		case "cardmarket":
			return "cardmarket_id", lastPathSegment(segments)
		default:
			if len(segments) == 3 {
				return "set_collector", segments[1] + "\x00" + segments[2]
			}
		}
	}
	if resourceType == "sets" && len(segments) >= 2 && segments[0] == "sets" {
		if len(segments) == 3 && segments[1] == "tcgplayer" {
			return "tcgplayer_id", lastPathSegment(segments)
		}
		if len(segments) == 2 {
			return "code", segments[1]
		}
	}
	return "", ""
}

type localDetailMatcher func(map[string]any) bool

func scryfallLocalDetailMatcher(resourceType, path string, params map[string]string) (localDetailMatcher, string, error) {
	segments := strings.Split(strings.Trim(path, "/"), "/")
	if resourceType == "cards" && len(segments) >= 2 && segments[0] == "cards" {
		switch segments[1] {
		case "named":
			exact := strings.TrimSpace(params["exact"])
			if exact == "" {
				return nil, "", fmt.Errorf("local data cannot safely reproduce Scryfall fuzzy-name lookup; provide --exact or use --data-source live")
			}
			setCode := strings.TrimSpace(params["set"])
			return func(object map[string]any) bool {
				if !localFieldMatches(object["name"], exact, true) {
					return false
				}
				return setCode == "" || localFieldMatches(object["set"], setCode, true)
			}, fmt.Sprintf("card named %q", exact), nil
		case "arena":
			return scalarLocalMatcher("arena_id", lastPathSegment(segments)), fmt.Sprintf("card with arena_id %q", lastPathSegment(segments)), nil
		case "mtgo":
			return scalarLocalMatcher("mtgo_id", lastPathSegment(segments)), fmt.Sprintf("card with mtgo_id %q", lastPathSegment(segments)), nil
		case "multiverse":
			return scalarLocalMatcher("multiverse_ids", lastPathSegment(segments)), fmt.Sprintf("card with multiverse_id %q", lastPathSegment(segments)), nil
		case "tcgplayer":
			return scalarLocalMatcher("tcgplayer_id", lastPathSegment(segments)), fmt.Sprintf("card with tcgplayer_id %q", lastPathSegment(segments)), nil
		case "cardmarket":
			return scalarLocalMatcher("cardmarket_id", lastPathSegment(segments)), fmt.Sprintf("card with cardmarket_id %q", lastPathSegment(segments)), nil
		}
		if len(segments) == 3 {
			setCode, collectorNumber := segments[1], segments[2]
			return func(object map[string]any) bool {
				return localFieldMatches(object["set"], setCode, true) && localFieldMatches(object["collector_number"], collectorNumber, true)
			}, fmt.Sprintf("card %q/%q", setCode, collectorNumber), nil
		}
	}

	if resourceType == "sets" && len(segments) >= 2 && segments[0] == "sets" {
		if len(segments) == 3 && segments[1] == "tcgplayer" {
			id := lastPathSegment(segments)
			return scalarLocalMatcher("tcgplayer_id", id), fmt.Sprintf("set with tcgplayer_id %q", id), nil
		}
		if len(segments) == 2 {
			code := segments[1]
			return func(object map[string]any) bool {
				return localFieldMatches(object["code"], code, true) || localFieldMatches(object["mtgo_code"], code, true)
			}, fmt.Sprintf("set with code %q", code), nil
		}
	}

	return nil, "", nil
}

func scalarLocalMatcher(field, value string) localDetailMatcher {
	return func(object map[string]any) bool {
		return localFieldMatches(object[field], value, false)
	}
}

func localFieldMatches(value any, wanted string, foldCase bool) bool {
	switch values := value.(type) {
	case []any:
		for _, candidate := range values {
			if localFieldMatches(candidate, wanted, foldCase) {
				return true
			}
		}
		return false
	}
	actual := store.ResourceIDString(value)
	if foldCase {
		return strings.EqualFold(actual, wanted)
	}
	return actual == wanted
}

func lastPathSegment(segments []string) string {
	if len(segments) == 0 {
		return ""
	}
	return segments[len(segments)-1]
}

// Ensure time import is used (compilation guard).
var _ = time.Now
